extends Node
## Task 62 / feel-2 item 5 (headless): the stone texture sticks to the stone. rock.gdshader takes its grain, specks, moss
## and beds from an OBJECT-space coordinate for loose stones: a node-drawn stone (flying, held: StoneBatch.lone_mesh)
## uses its model-space VERTEX (local_pos = 1), a batched one (lying: StoneBatch.rebuild) a per-vertex CUSTOM0 that holds
## the model-space vertex, so a stone looks the same moving, rotating and after it lands.
## Run: godot --headless --path . res://world/rocks/rock_look_test.tscn
## Lines: LOOK_CHECK name ok|FAIL, LOOK_DONE fails=N.

var fails := 0


func _ready() -> void:
	_run.call_deferred()


func _check(name: String, ok: bool, extra := "") -> void:
	print("LOOK_CHECK %s %s %s" % [name, "ok" if ok else "FAIL", extra])
	if not ok:
		fails += 1


func _cpu(kind: String, seed_: int) -> CpuMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = seed_
	var skin := RockMesh.material(kind)
	var fresh := RockMesh.fresh_material(kind)
	var out := CpuMesh.new()
	for mat in [skin, fresh]:
		var v := PackedVector3Array()
		for i in 12:
			v.append(Vector3(rng.randf_range(-0.2, 0.2), rng.randf_range(-0.15, 0.15), rng.randf_range(-0.2, 0.2)))
		out.add(v, StoneMesh.face_normals(v), PackedVector2Array(), mat)
	return out


func _stone(id: int, kind: String, xf: Transform3D, bed: Vector3):
	var s := StoneSystem.Stone.new()
	s.id = id
	s.kind = kind
	s.mesh = _cpu(kind, id)
	s.xf = xf
	s.bed = bed
	return s


func _run() -> void:
	await get_tree().process_frame
	var rng := RandomNumberGenerator.new()
	rng.seed = 5
	for kind in ["granite", "sandstone", "limestone", "flint", "coal"]:
		var bed := Vector3(0.3, 0.9, 0.1).normalized() if kind == "sandstone" else Vector3.ZERO
		var a := _stone(1, kind, Transform3D(Basis.IDENTITY, Vector3(3, 1, 4)), bed)
		var b := _stone(1, kind, Transform3D(Basis(Quaternion(Vector3(rng.randf(), rng.randf(), rng.randf()).normalized(), 2.1)),
			Vector3(-40, 7, 12)), bed)
		var ba := StoneBatch.new()
		ba.ids = [1]
		var bb := StoneBatch.new()
		bb.ids = [1]
		if not ba.has_method("collect"):
			_check("%s batch collect" % kind, false, "StoneBatch.collect missing (no object-space attribute)")
			continue
		var ra: Dictionary = ba.collect({1: a})
		var rb: Dictionary = bb.collect({1: b})
		var ok := ra.size() == rb.size() and not ra.is_empty()
		var worst := 0.0
		for bk in ra:
			var la: PackedVector3Array = ra[bk][6]
			var lb: PackedVector3Array = rb[bk][6]
			var wa: PackedVector3Array = ra[bk][0]
			ok = ok and la.size() == wa.size() and la.size() == lb.size()
			for i in la.size():
				worst = maxf(worst, (la[i] - lb[i]).length())                       # same local vertex, other pose
				worst = maxf(worst, (la[i] - a.xf.affine_inverse() * wa[i]).length())   # = the inverse of its pose
			var ua: PackedVector2Array = ra[bk][4]
			var ub: PackedVector2Array = rb[bk][4]
			ok = ok and ua == ub                                                   # bed normal in model space
		_check("%s batch local vertex pose-independent" % kind, ok and worst < 1e-5, "err=%.2g m" % worst)
		var mat_b := ra[ra.keys()[0]][5] as ShaderMaterial
		_check("%s batch material reads CUSTOM0" % kind, mat_b.get_shader_parameter("batch_local") == 1.0)
		var lm := StoneBatch.lone_mesh(kind, a.mesh, a.bed)
		var mat_n := lm.surface_get_material(0) as ShaderMaterial
		_check("%s node material uses model VERTEX" % kind, float(mat_n.get_shader_parameter("local_pos")) == 1.0
			and float(mat_n.get_shader_parameter("batch_local")) == 0.0)
	print("LOOK_DONE fails=%d" % fails)
	get_tree().quit(fails)
