extends Node
## feel2 stone L1: where does the crash cutter fold? -- file=<bin>
func _arg(k: String, d: String) -> String:
	for a in OS.get_cmdline_user_args():
		if a.begins_with(k + "="):
			return a.substr(k.length() + 1)
	return d

static func seg_tri(p: Vector3, q: Vector3, t: PackedVector3Array, o: int, eps := 1e-12) -> bool:
	var e1 := t[o + 1] - t[o]
	var e2 := t[o + 2] - t[o]
	var d := q - p
	var h := d.cross(e2)
	var a := e1.dot(h)
	if absf(a) < 1e-18:
		return false
	var f := 1.0 / a
	var s := p - t[o]
	var u := f * s.dot(h)
	if u < -eps or u > 1 + eps:
		return false
	var qq := s.cross(e1)
	var v := f * d.dot(qq)
	if v < -eps or u + v > 1 + eps:
		return false
	var tt := f * e2.dot(qq)
	return tt >= -eps and tt <= 1 + eps

static func shares(t: PackedVector3Array, i: int, j: int) -> bool:
	for a in 3:
		for b in 3:
			if t[i * 3 + a].distance_to(t[j * 3 + b]) < 1e-9:
				return true
	return false

static func pairs(t: PackedVector3Array) -> Array:
	var out := []
	var n := t.size() / 3
	for i in n:
		for j in range(i + 1, n):
			if shares(t, i, j):
				continue
			var hit := false
			for k in 3:
				if seg_tri(t[i * 3 + k], t[i * 3 + (k + 1) % 3], t, j * 3) or seg_tri(t[j * 3 + k], t[j * 3 + (k + 1) % 3], t, i * 3):
					hit = true
					break
			if hit:
				out.append(Vector2i(i, j))
	return out

func _ready() -> void:
	var fa := FileAccess.open(_arg("file", ""), FileAccess.READ)
	var d: Dictionary = fa.get_var()
	var c: PackedVector3Array = d.cutter
	print("cutter tris ", c.size() / 3)
	for p: Vector2i in pairs(c):
		print("PAIR ", p, " ", (c[p.x*3]+c[p.x*3+1]+c[p.x*3+2])/3.0, " ", (c[p.y*3]+c[p.y*3+1]+c[p.y*3+2])/3.0)
	get_tree().quit()
EOF
